8	// The numbered steps DevDesk writes for the findings it builds itself
9	// (DEVDESK-752). Every function here is pure: the caller says what it ran and
10	// what the tool printed. A step is one imperative sentence in English US with
11	// one action; alternatives are separate steps. The Resolution of the same
12	// finding is untouched.
13	
14	// kustomizeMountStep is added for a kustomize image that could not find a path
15	// (see mountResolution): the container sees only what DevDesk mounts.
16	const kustomizeMountStep = "If this reference points outside the directory DevDesk mounts into the container, " +
17		"scan the enclosing directory or set scan.tools.kustomize.source: binary."
18	
19	// isLoadRestrictor reports whether kustomize refused a file outside the overlay
20	// directory.
21	func isLoadRestrictor(detail string) bool {
22		return strings.Contains(detail, "security; file") && strings.Contains(detail, "is not in or below")
23	}
24	
25	// typedDir is a folder as the user is told to type it after helm
26	// (DEVDESK-768). A name that starts with "-" would be read as an option, so it
27	// gets the "./" the scan itself uses (asPathArg); any other folder keeps its
28	// plain name, which the same command accepts. Only the command's argument goes
29	// through it: a title, a file or a sentence names the folder as it is.
30	func typedDir(dir string) string {
31		if strings.HasPrefix(dir, "-") {
32			return "./" + dir
33		}
34		return dir
35	}
36	
37	// typedKustomizeDir is typedDir for kustomize, which also reads a relative name
38	// as a remote git base when its first segment holds a ".", a ":" or an "@"
39	// (github.com/org/repo, git@host:o/r, DEVDESK-763). Those get the "./" of
40	// asPathArg too; an ordinary folder stays bare.
41	func typedKustomizeDir(dir string) string {
42		first, _, _ := strings.Cut(dir, "/")
43		if (first != "." && first != ".." && strings.ContainsAny(first, ".:@")) || strings.HasPrefix(dir, "-") {
44			return asPathArg(dir)
45		}
46		return dir
47	}
48	
49	// renderSteps are the steps for a chart or an overlay that did not render.
50	// target is the overlay directory or the chart, relative to the scanned
51	// directory; detail is what the tool printed. blocked says the failure is a
52	// remote base the cut network refused (the caller's remoteBlocked, asked only of
53	// an offline run): it gets steps of its own.
54	func renderSteps(source, target string, from ToolSource, detail string, blocked bool) []string {
55		if source != SourceKustomize {
56			return []string{
57				fmt.Sprintf("Run helm template %s and fix the first error it reports.", typedDir(target)),
58				fmt.Sprintf("If a dependency is missing, run helm dependency build %s.", typedDir(target)),
59			}
60		}
61		var steps []string
62		switch {
63		case blocked:
64			return []string{
65				fmt.Sprintf("Copy the remote base that %s names into the repository and reference it by a relative path.", target),
66				"Or set scan.tools.kustomize.allow_remote_bases: true if you trust this repository.",
67			}
68		case isLoadRestrictor(detail):
69			steps = []string{
70				"Reference a directory that has its own kustomization.yaml, or",
71				fmt.Sprintf("move the file below %s.", target),
72			}
73		default:
74			steps = []string{fmt.Sprintf("Run kustomize build %s and fix the first error it reports.", typedKustomizeDir(target))}
75		}
76		if from == ToolSourceContainer &&
77			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
78			steps = append(steps, kustomizeMountStep)
79		}
80		return steps
81	}
82	
83	// helmLintSteps are the steps for one message of helm lint: file is the finding's
84	// file and chart the chart directory.
85	func helmLintSteps(file, chart string) []string {
86		return []string{
87			fmt.Sprintf("Fix what helm lint reports in %s.", file),
88			fmt.Sprintf("Run helm lint %s again to confirm.", typedDir(chart)),
89		}
90	}
91	
92	// schemaSteps are the steps for a field the schema rejected. rendered is "" for
93	// a plain manifest and the renderer's dialect (helm, kustomize) for a rendered
94	// one.
95	func schemaSteps(r kubeconformResource, p kubeconformFieldProblem, version, rendered string) []string {
96		field := p.Path
97		if m := additionalProperty.FindStringSubmatch(p.Msg); m != nil {
98			field = strings.TrimSuffix(p.Path, "/") + "/" + m[1]
99		}
100		if field == "" {
101			field = "the resource"
102		}
103		release := "Kubernetes"
104		if version != "" {
105			release += " " + version
106		}
107		steps := []string{fmt.Sprintf("Correct %s so it matches the %s %s schema of %s.", field, r.Version, r.Kind, release)}
108		if rendered != "" {
109			steps = append(steps, fmt.Sprintf("Render it with %s and validate the output against %s.", rendered, release))
110		}
111		return steps
112	}
