114	// secretSteps are the steps for a secret Gitleaks or Trivy found. It returns a
115	// new slice on every call: a shared one would let a caller change every finding.
116	func secretSteps() []string {
117		return []string{
118			"Revoke or rotate this secret where it was issued: treat it as exposed.",
119			"Remove it from the file and read it from a secret store or an environment variable.",
120		}
121	}
