76	func stepProblems(steps []string) []string {
77		var problems []string
78		seen := map[string]bool{}
79		for i, s := range steps {
80			label := fmt.Sprintf("step %d %q", i+1, s)
81			switch {
82			case s == "":
83				problems = append(problems, label+": empty")
84				continue
85			case s != strings.TrimSpace(s) || strings.ContainsAny(s, "\n\r\t"):
86				problems = append(problems, label+": blanks around it or a line break inside")
87			}
88			for _, re := range keyNamePatterns {
89				if m := re.FindString(s); m != "" {
90					problems = append(problems, fmt.Sprintf("%s: names a key (%q)", label, m))
91				}
92			}
93			afterAlternative := i > 0 && steps[i-1] == loadRestrictorAlternative && strings.HasPrefix(s, legacyAlternativePartner)
94			first, _ := utf8.DecodeRuneInString(s)
95			if !unicode.IsUpper(first) && !afterAlternative {
96				problems = append(problems, label+": does not start with a capital letter")
97			}
98			last := i == len(steps)-1
99			switch {
100			case strings.HasSuffix(s, "."):
101			case s == loadRestrictorAlternative && !last && strings.HasPrefix(steps[i+1], legacyAlternativePartner):
102			default:
103				problems = append(problems, label+": does not end with a period")
104			}
105			if seen[s] {
106				problems = append(problems, label+": appears twice")
107			}
108			seen[s] = true
109		}
110		return problems
111	}
