				}
			}
		})
	}
}

// The fallback is the same sentence for the two helm steps of a chart, which
// stepProblems refuses as a duplicate: they must read differently, or be one.
func TestTheTextForAFolderNameThatNeedsQuotingIsNotRepeated(t *testing.T) {
	steps := renderSteps(SourceHelm, "x\ntouch pwned", ToolSourceBinary, "boom", false)
	if len(steps) == 0 {
		t.Fatal("no step for a chart whose name needs quoting")
	}
	for _, p := range stepProblems(steps) {
		t.Error(p)
	}
}

